import React from 'react'

function getItemPrice(price){
    return price > 15000 ? 'expensive' : 'cheap';
}

function getItemContent(items){
    return `hey this is ${items.name} which is ${getItemPrice(items.price)}`
}

// normal function
function Cars({props}){
    return<>
    <div>
{
    this.props.carItems.map((items,index)=>
        <div>{index+1}. {getItemContent(items)}</div>

    )
}

    </div>
    </>
}

export default Cars;
